    oui:['Oui', 'Yes', 'Sí', 'Ja', 'Sì', 'Sim'], non:['Non', 'No', 'No', 'Nein', 'No', 'Não'],
    pyQ:['Qu’affiche ce programme Python ?', 'What does this Python program print?', '¿Qué muestra este programa en Python?', 'Was gibt dieses Python-Programm aus?', 'Che cosa stampa questo programma Python?', 'O que mostra este programa em Python?'],
    pyE:['range({a}, {b}) donne les entiers de {a} à {c} : on additionne ou on applique la fonction pas à pas.', 'range({a}, {b}) gives the whole numbers from {a} to {c}: add them or apply the function step by step.', 'range({a}, {b}) da los enteros de {a} a {c}: se suman o se aplica la función paso a paso.', 'range({a}, {b}) liefert die ganzen Zahlen von {a} bis {c}: man addiert sie oder wendet die Funktion Schritt für Schritt an.', 'range({a}, {b}) dà gli interi da {a} a {c}: si sommano o si applica la funzione passo per passo.', 'range({a}, {b}) dá os inteiros de {a} a {c}: somam-se ou aplica-se a função passo a passo.'],
